const http = require('http');

const entries = [];

const MONTH_RE = /^\d{4}-(0[1-9]|1[0-2])$/;

const server = http.createServer((req, res) => {
  const url = new URL(req.url, 'http://localhost');

  if (req.method === 'POST' && url.pathname === '/entries') {
    let body = '';
    req.on('data', (c) => { body += c; });
    req.on('end', () => {
      const { amount, note } = JSON.parse(body || '{}');
      entries.push({ id: entries.length + 1, amount, note, ts: Date.now() });
      res.end('ok');
    });
    return;
  }
  if (req.method === 'GET' && url.pathname === '/entries') {
    const month = url.searchParams.get('month');
    let result = entries;
    if (month !== null) {
      if (!MONTH_RE.test(month)) {
        res.statusCode = 400;
        res.setHeader('content-type', 'application/json');
        res.end(JSON.stringify({ error: 'invalid month; expected YYYY-MM' }));
        return;
      }
